head.script:
scwin.trigger1_onclick = function(e) {
    result = JSON.stringify(widgetContainer1.exportWidget('widget2'));
    //alert( JSON.stringify(widgetContainer1.exportWidget('widget2')) );
};
scwin.trigger11_onclick = function(e) {
    isSuccess = widgetContainer1.importWidget('widget0', {
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1,
        title: "개별 import test"
    });
};
scwin.trigger13_onclick = function(e) {
    result = widgetContainer1.exportWidget('');
};
scwin.trigger14_onclick = function(e) {
    isSuccess = widgetContainer1.importWidget('widget5', {
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1,
        title: "개별 import test"
    });
};
scwin.test = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "trigger1.click()");
    WebSquare.wUnit.addCommand("assert", "result == JSON.stringify( widgetContainer1.getWidgetById('widget2').getWidgetInfo() )", "true");
    WebSquare.wUnit.addCommand("set", "trigger11.click()");
    WebSquare.wUnit.addCommand("assert", "isSuccess", "true");
    WebSquare.wUnit.addCommand("assert", "widgetContainer1.getWidgetById('widget0').getWidgetInfo().title", "개별 import test");
    WebSquare.wUnit.addCommand("set", "trigger13.click()");
    WebSquare.wUnit.addCommand("assert", "result == null", "true");
    WebSquare.wUnit.addCommand("set", "trigger14.click()");
    WebSquare.wUnit.addCommand("assert", "isSuccess", "false");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload = function() {
    window.result = "", isSuccess = false;
    for (var i = 0; i < 5; i++) {
        widgetContainer1.addWidgets({
            id: "widget" + i,
            title: "위젯" + i,
            scope: true,
            x: 0,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        });
    }
    scwin.test();
}
